import{_ as t,c as o,a,o as n}from"./app-DPQeTMaU.js";const s={};function r(i,e){return n(),o("div",null,[...e[0]||(e[0]=[a('<h2 id="p151-160" tabindex="-1"><a class="header-anchor" href="#p151-160"><span>P151-160</span></a></h2><h3 id="_151-advanced-darwin-s-theory-of-evolution" tabindex="-1"><a class="header-anchor" href="#_151-advanced-darwin-s-theory-of-evolution"><span>[151] Advanced - Darwin&#39;s Theory Of Evolution</span></a></h3><p>A: Man, it&#39;s been forever. Where have you been up lately?</p><p>B: I&#39;ve been busy preparing for my exams, not to mention all the term papers I have to write.</p><p>A: Same here. <strong>I&#39;m up to my neck in work</strong>, but at least glad that summer holiday is after finals. Where&#39;re you heading now?</p><p>B: I&#39;m going to my Anthropology class. We&#39;ve been focus on Darwin all term since the 200th anniversary of his birth or whatever. I&#39;m <strong>sick and tired</strong> of Darwin, Darwin, Darwin!</p><p>A: What? Why? How can you not like Darwin? His work contains thousands of years of ideas about creation <strong>on their head</strong>. His theory of evolution <strong>revolutionized</strong> the field of Biology and the Anthropology.</p><p>B: I don&#39;t like him. His theory of <strong>human evolution</strong> and <strong>natural selection</strong> is full of holes. It&#39;s not as solid as you made it out to be.</p><p>A: Say that again and you will make enemy of half of the academy. Not to mention your professors! Furthermore, the explanation proposed by Darwin about <strong>the origin of species</strong> and the process of natural selection constitutes a grand step toward a coherent understanding of the world and it very beginnings.</p><p>B: I&#39;m not minimizing his huge contributions to science, it&#39;s just that his theory reminds me of the <strong>conundrum</strong> of the chicken and the egg.</p><p>A: What are you talking about?</p><p>B: Which came first? The chicken or the egg? This is a classic logical problem and I think it priors to Darwin&#39;s theory. How did the very first living organism come to be?</p><p>A: Interesting. I think that question is better suited for my philosophy class. In the meantime, how about we settle this. . . with a due!</p><h3 id="_152-the-office-cut-it-out" tabindex="-1"><a class="header-anchor" href="#_152-the-office-cut-it-out"><span>[152] The Office - Cut It Out</span></a></h3><p>A: Hey, Mary, can you <strong>cut that out</strong>?</p><p>B: Cut what out, I&#39;m not doing anything.</p><p>A: The tapping of your pen on your desk. It&#39;s <strong>driving me crazy</strong>.</p><p>B: Fine! By the way, would you mind not <strong>slurping</strong> your coffee every time you have a cup!</p><p>A: I don&#39;t slurp my coffee. And plus, how can you hear it when you&#39;re shouting into your phone all the time?</p><p>B: <strong>You&#39;ve got to be kidding me</strong>! You&#39;re complaining about me talking on the phone when you go out for a cigarette break ten times a day to <strong>shoot the breeze</strong>?</p><p>A: Look, we have a lot of <strong>accumulated</strong> anger from working in these conditions, and it&#39;s probably okay to let off steam once in a while, But it&#39;s probably not a good idea to keep it up, I&#39;m willing to <strong>forgive and forget</strong>, if you are.</p><p>B: Fine. Let&#39;s <strong>call a truce</strong>. I&#39;ll try to more <strong>considerate</strong> and to keep the noise down</p><p>A: Yeah, I&#39;ll try to do the same. So, I was wondering you wanna go out to dinner Friday night?</p><h3 id="_153-daily-life-homesick" tabindex="-1"><a class="header-anchor" href="#_153-daily-life-homesick"><span>[153] Daily Life - Homesick</span></a></h3><p>A: Tom! How are you? We missed you at the party last night. Are you ok?</p><p>B: I don&#39;t know. I didn&#39;t really feel like going out. I guess I&#39;m feeling a little <strong>homesick</strong>.</p><p>A: Come on <strong>We&#39;ve been through this already</strong>! Look, I know the <strong>adjustment</strong> was hard when you first got here, but we agreed that you were gonna try and deal with it.</p><p>B: I was. It&#39;s just that the holidays are coming up and I won&#39;t be able to go home because I can&#39;t afford the airfare. I&#39;m just longing for some of the <strong>comforts of home</strong>, like my mom&#39;s cooking and being around my family.</p><p>A: Yeah, it can get pretty lonely over the holidays. When I first got here, I&#39;d get depressed and <strong>nostalgic</strong> for anything that reminded me of home. I almost let it get to me, but then I started going out, keeping myself busy and before I knew it, I was used to it.</p><p>B: I see what you mean, but I &#39;m still <strong>bummed out</strong>.</p><p>A: Ok how does this sound: let&#39;s get you suited up and <strong>hit the dance club</strong> tonight. I hear that an awesome DJ is playing and there will be a lot of pretty single girls there!</p><p>B: You know, I could really go for that. You don&#39;t mind being my <strong>wingman</strong> for tonight?</p><p>A: Not at all! It be fun! It will be like a <strong>boys night out</strong>... well kinda...</p><p>B: Great! I must warn you though, whatever happens, don&#39;t let me go on a <strong>drinking binge</strong>. Trust me, it&#39;s not a pretty picture!</p><h3 id="_154-the-weekend-rock-band" tabindex="-1"><a class="header-anchor" href="#_154-the-weekend-rock-band"><span>[154] The Weekend - Rock Band</span></a></h3><p>A: I&#39;m forming a music band.</p><p>B: Do you already know how to play an <strong>instrument</strong>?</p><p>A: Uh... Yeah! I&#39;ve told you a thousand times that I&#39;m learning to play the <strong>drums</strong>. Now that I know how to play well, I would like to form a rock band.</p><p>B: Aside from yourself, who are the other members of the band?</p><p>A: We have a guy who plays guitar, and another who plays bass. Although we still haven&#39;t found anyone to be our singer. You told me that you had musical talent, right?</p><p>B: Yes, I&#39;m a singer.</p><p>A: Perfect. So you can <strong>audition</strong> this weekend here at my house.</p><p>B: Great! Wait here? You don&#39;t have enough room for the amplifiers, microphones or even your drums! By the way where do you keep them or practice?</p><p>A: Dude? What are you talking about? It&#39;s right here! All we need is my Nintendo Wii and we are set!</p><h3 id="_155-the-weekend-bachelor-party" tabindex="-1"><a class="header-anchor" href="#_155-the-weekend-bachelor-party"><span>[155] The Weekend - Bachelor Party</span></a></h3><p>A: Hi honey! <strong>You&#39;ll never guess what</strong>! My friends Julie and Alex are getting married!</p><p>B: Wow that&#39;s great news! They&#39;re a great couple!</p><p>A: I know! Anyways I just talked to Alex&#39;s <strong>best man</strong> and he is organizing the bachelor party It&#39;s gonna be so much fun! All the <strong>groomsmen</strong> are thinking up all the wacky and crazy things we are going to do that night.</p><p>B: You aren&#39;t going to a <strong>strip club</strong> are you? I don&#39;t want you getting a <strong>lap</strong> dance from some stripper with the excuse that it&#39;s your friends party.</p><p>A: Aw come on! It&#39;s just some innocent fun! <strong>You know how these things are</strong>! We are gonna play drinking games, get him some <strong>gag gifts</strong> and just have a good time.<strong>Nothing too over the top</strong>.</p><p>B: Well, I don&#39;t know.</p><p>A: Come on! If one of your friends was getting married, I wouldn&#39;t mind you going to her bachelorette party!</p><p>B: Good,because my friend Wendy is getting married and I&#39;m organizing her party!</p><p>A: What!</p><h3 id="_156-the-weekend-scary-story" tabindex="-1"><a class="header-anchor" href="#_156-the-weekend-scary-story"><span>[156] The Weekend - Scary Story</span></a></h3><p>A: Oh no! The lights went out! Honey can you light a candle?</p><p>B: Sure. What do we do now?</p><p>A: Well, we can just talk, you know, like we used to.</p><p>B: Hmm... I know! I&#39;ll tell you a scary story! It happened to me and my dad when I was a teenager...I was living with my father at the time, when he received a phone call.</p><p>C: Hello? Yes this is him. I see, I&#39;m sorry to hear that. Ok no problem. I&#39;ll be there shortly. Pack some clothes Tony, my great aunt is very ill and no one in the family wants to take care of her. We are going to stay at her house for a few days.</p><p>B: Aunt? What aunt? I never knew you had a <strong>great aunt</strong>!</p><p>C: Well, the family doesn&#39;t talk about her or get near her, for that matter.</p><p>B: Why is that?</p><p>C: Come on, we have to go.</p><p>B: So we arrived at this old house on the outskirts of our town. There was almost no one around and the house had an eerie look to it. Once inside the house, we walked to her room and I was surprised to find my dad&#39;s great aunt in a wheelchair, yelling at someone, but we were alone in the room.</p><p>C: Hi, aunt Ursula! This is my son Tony.</p><p>D: Why have you come? Why are you here? Don&#39;t you know it isn&#39;t safe? <strong>My time is near</strong>, he is coming for me.</p><p>B: Who is coming for you?</p><p>D: <strong>The prince of darkness! The lord of the underworld, the tempter, the old serpent.</strong></p><p>C: Come on, aunt Ursula let&#39;s lay you down. You need to get some rest. Tony, help me lay her down.</p><p>B: That night, we slept in one of the 12 rooms of that big old mansion. The trees outside seemed to come alive and their shadows formed ghoulish shapes on my bed. All of a sudden, we heard screaming.</p><p>D: Ahhh! Get off me beast! I won&#39;t let you take me! Ahhh!</p><p>B: Dad! Dad! Something is attacking aunt Ursula!</p><p>D: Take your claws off me! Go back to the underworld you demon! I shall <strong>be judged</strong> before you can take me!</p><p>C: The door is jammed! Stand back! Aunt Ursula! Where are you?</p><p>B: Over here!</p><p>B: And as we approached her, she was lying on the floor, with her hands and feet open like the Vitruvian Man, breathing heavily with bloody marks and scratches on her arms, legs and face. Remember how I mentioned that she was in a wheelchair? My aunt had been paralyzed from the neck down for just over a year. After this incident, strange things would happen in the house and my aunt would yell and scream, according to her, warding off the evil that had come to get her. As the days passed, she became very weak and eventually was unable to talk. My dad had to work during the day, so I was left to care for her. When she lost her voice and laid on her death bed, I would hear her breathe, in and out. Until finally one day, she breathed in... and never exhaled. That night, I felt relieved that it was finally over, but it wasn&#39;t. I was so terrified of what I was hearing, that I didn&#39;t sleep all night. The following morning, I went to the bathroom, expecting to find a mess and everything torn up, but I found everything exactly as it was before. The movers came that same day and as we were cleaning out her drawers and personal items, we found strange notebooks with names and amounts of money written next to them. We found pictures with people&#39;s faces sewn with black or red string. And you want to know what the strangest thing was? There was a small doll, filled with dead ants, with a strand of hair tied around its waist, and on the doll&#39;s face, there was a picture of me with the numbers: &quot;311009&quot;. You know what date it is today? October 31st, 2009...</p><h3 id="_157-the-weekend-trick-or-treat" tabindex="-1"><a class="header-anchor" href="#_157-the-weekend-trick-or-treat"><span>[157] The Weekend - Trick Or Treat</span></a></h3><p>A: <strong>Trick-or-treat</strong></p><p>B: Tom, <strong>aren&#39;t you</strong> a little too old to be trick-or-treating?</p><p>A: What are you talking about? Where is your Halloween spirit? Didn&#39;t you ever dress up in a costume and go around the neighborhood trick-or-treating with your friends?</p><p>B: Of course I did, but when I was ten! Trick-or-treating is for kids, plus, I&#39;m sure people will think you&#39;re a <strong>kidnapper</strong> or something, running around with kids at night.</p><p>A: Whatever, I&#39;m going next door. I heard Mrs.Robinson is giving out big bags of <strong>M&amp;Ms</strong>!</p><h3 id="_158-global-view-all-saints-day" tabindex="-1"><a class="header-anchor" href="#_158-global-view-all-saints-day"><span>[158] Global View - All Saints Day</span></a></h3><p>C: The Day of the Dead has arrived. All Soul&#39;s Day and All Saint&#39;s Day!</p><p>A: Your neighbor is crazy. Why is he screaming that?</p><p>B: Because today is the first of November: the Day of the Dead</p><p>A: Oh, that&#39;s right.</p><p>B: This is a very special day among many cultures around the world especially in Latin America</p><p>A: Seriously? I thought it was just like any other day, except for the fact that people visit the cemetery and remember their <strong>loved ones</strong>.</p><p>B: Well, that&#39;s just part of it. People across the world celebrate in different ways. In Mexcio for example it&#39;s common to see people building private <strong>altars</strong> honoring the <strong>deceased</strong> using <strong>sugar skulls</strong>, preparing the favorite foods and beverages of the departed and visiting graves with these as gifts. In the Philippines , the <strong>tombs</strong> are cleaned or repainted, candles are lit and flowers are offered. Entire families camp out in cemeteries and sometimes spend a night or two near their relatives&#39; tombs!</p><p>A: Whoa! That&#39;s scary! I don&#39;t know if I could do that!</p><p>B: Why? We should fear the living, not the dead .</p><h3 id="_159-daily-life-getting-flowers" tabindex="-1"><a class="header-anchor" href="#_159-daily-life-getting-flowers"><span>[159] Daily Life - Getting Flowers</span></a></h3><p>A: Hello sir, how may I help you?</p><p>B: I would like to buy some flowers, please. Something really nice.</p><p>A: I see, may I ask what the occasion is?</p><p>B: It&#39;s not really an occasion, it&#39;s more like I&#39;m sorry.</p><p>A: Very well. This arrangement here is very popular among regretful husbands and boyfriends. It has a dozen long stem red roses with a couple of <strong>sunflowers</strong> and a single orchid that stands out. It includes a small teddy bear to achieve the effect of immediate forgiveness.</p><p>B: I think I&#39;m gonna need more than just a dozen red roses and a bear. What else do you recommend?</p><p>A: Mmm, well this is our &quot;I&#39;m sorry I <strong>cheated on</strong> you&quot; package. Two dozen red roses lined with <strong>tulips</strong>, <strong>carnations</strong> and <strong>lilies</strong>. The fragrance and beauty of this flower arrangement is sure to make her forgive you.</p><p>B: I don&#39;t think <strong>that&#39;s gonna cut it</strong>. I need something bigger and better!</p><p>A: I&#39;m sorry sir but, what exactly did you do?</p><p>B: Well, I may have accidentally <strong>insinuated</strong> that she is getting <strong>chubbier</strong>.</p><p>A: Get out of my store you jerk!</p><h3 id="_160-global-view-health-insurance" tabindex="-1"><a class="header-anchor" href="#_160-global-view-health-insurance"><span>[160] Global View - Health Insurance</span></a></h3><p>A: Hey honey, how was your day?</p><p>B: It was alright. I ran into Bill and <strong>we got to talking for a while</strong>. He&#39;s <strong>in a bit of a jam</strong>.</p><p>A: Why? What happened?</p><p>B: Well, his son had an accident and Bill doesn&#39;t have health insurance. <strong>This really got me thinking</strong>, and I wondered if we should look into a couple of different <strong>HMO</strong>&#39;s.</p><p>A: Yeah, you&#39;re right. We aren&#39;t getting any younger and our kids are getting older.</p><p>B: Exactly! I searched on the web and found a couple of HMO&#39;s with low <strong>copays</strong> and good <strong>coverage</strong>. The <strong>deductibles</strong> are low, too.</p><p>A: Sounds good, although, do you think we can <strong>qualify for</strong> insurance? Those insurance companies are real pirates when it comes to money.</p><p>B: Well, we don&#39;t have any <strong>preexisting</strong> illnesses or conditions, so we should be fine.</p><p>A: I wish our company or country provided us with health care.</p><p>B: Not in a million years!</p><h2 id="p161-170" tabindex="-1"><a class="header-anchor" href="#p161-170"><span>P161-170</span></a></h2><h3 id="_161-daily-life-computer-games" tabindex="-1"><a class="header-anchor" href="#_161-daily-life-computer-games"><span>[161] Daily Life - Computer Games</span></a></h3><p>A: Mark, Where have you been? I&#39;ve been calling you all morning.</p><p>B: I&#39;ve been playing computer games.</p><p>A: What? So you <strong>blew me off</strong> yesterday and today over a stupid video game? What game is so important that you have no time for me anymore? What are you playing?</p><p>B: It&#39;s called <strong>Counter Strike</strong> It&#39;s a <strong>first person shooter</strong> game. It&#39;s awesome. It&#39;s a multiplayer game where you can <strong>go online</strong> and compete against players from all over the world.</p><p>A: You&#39;ve been <strong>wasting your time</strong> on this? I can&#39;t believe it! It doesn&#39;t even look fun or challenging!</p><p>B: My laptop is on my bed. If you think it&#39;s so easy then get online and try to beat me.</p><p>A: Fine!</p><p>B: Damn it! How are you killing me with a single shot? It&#39;s not fair! I don&#39;t want to play anymore! Let&#39;s go get something to eat.</p><p>A: Can you bring me something? I am totally <strong>hooked</strong> on this game!</p><h3 id="_162-global-view-veteran-s-day" tabindex="-1"><a class="header-anchor" href="#_162-global-view-veteran-s-day"><span>[162] Global View - Veteran&#39;s Day</span></a></h3><p>A: Do you have any plans for <strong>Veteran</strong>&#39;s Day?</p><p>B: You mean <strong>Armistice</strong> Day?</p><p>A: <strong>What are you talking about</strong>? November 11th is Veteran&#39;s Day! <strong>What planet are you from</strong>?</p><p>B: Well, as you know, on November 11th, <strong>the allies</strong> signed a <strong>peace treaty</strong> with the Germans, also known as the Armistice Treaty. This marked the end of WWI and many countries around the world commemorate this date under names such as Remembrance day. In Poland it&#39;s their independence day! There&#39;s a lot going on around the world on this day.</p><p>A: Wow, I didn&#39;t know! Probably because I <strong>flunked</strong> history in school.</p><h3 id="_163-global-view-social-security" tabindex="-1"><a class="header-anchor" href="#_163-global-view-social-security"><span>[163] Global View - Social Security</span></a></h3><p>A: Well that was an interesting documentary!</p><p>B: For sure! I didn&#39;t really understand some of the technical <strong>jargon</strong> they used in the film when they talked about social security in the US.</p><p>A: Like what?</p><p>B: Well, they mentioned how people <strong>put away</strong> money in something called a <strong>401K</strong>?</p><p>A: Yeah, I know it sounds weird, but a 401k is a type of <strong>retirement plan</strong> that allows employees to save and invest for their own retirement. Through a 401k you can authorize your employer to <strong>deduct</strong> a certain amount of money from your paycheck and invest it in a 401k plan. Everyone tries to contribute as much as possible so that when you retire, you can rest peacefully on your <strong>nest egg</strong>.</p><p>B: That&#39;s interesting and logical I guess. In my country, we also have to contribute to a government-run retirement fund, but most people don&#39;t really trust it, so they just invest in properties or things like that.</p><p>A: That seems a bit unstable don&#39;t you think?</p><p>B: Yeah, but <strong>corrupt</strong> governments in the past have created <strong>distrust</strong> among banks and financial institutions, so now people prefer to have money hidden in a jar or a <strong>piggy bank</strong>.</p><p>A: I&#39;ve been thinking of doing that lately! I don&#39;t want some banker to run off with my money!</p><h3 id="_164-daily-life-apology-letter" tabindex="-1"><a class="header-anchor" href="#_164-daily-life-apology-letter"><span>[164] Daily Life - Apology Letter</span></a></h3><p>A: Dear Mary, I come here today, in this way, because I need to apologize to you. <strong>I failed you</strong>. Although I did not lie to you in words, I lied to you with faces that did not belong to me. I never meant to ruin the friendship that meant the world to me. <strong>You mean the world to me</strong> and now I come to you asking for forgiveness. If in your heart you find you can&#39;t, then I will understand and learn from this experience.</p><p>A: You came into my life at a time when I needed you the most. We talked about so many things that I started to realize my heart and my soul could actually feel something other than hurt. <strong>You placed comfort where there was fear</strong>, confidence where there was doubt, a shoulder where tears could fall and completeness where there was emptiness. I wanted to hold onto this so badly that I did whatever it took for you to notice. What I didn&#39;t realize was that I could lose my entire being, all of who I was and all that I had placed in you.</p><p>A: I wanted to be the one who would be there when you needed to talk. I wanted to be the comfort for your soul when the world was <strong>too much to handle</strong>. I wanted to be strong for you when everything else seemed impossible. I wanted to love you in only the way you deserved to be loved, never realizing that I was destroying myself and you. Somehow I needed you to be a part of my life. The only problem was that I was willing to <strong>jeopardize</strong> everything to get that done.</p><p>A: All the things that I told you about how I felt and how you make me feel were true. Nothing else mattered to me except hearing the laughter in your voice when you were happy. You made my days easy to get through and my nights peaceful; you helped me look forward to another day. Even though distance separated us, <strong>just being was enough</strong>.</p><p>A: I&#39;m sorry for hurting you and if I had to do all over again I would have been 100% with you. Forgive me please.</p><h3 id="_165-daily-life-asking-for-a-loan" tabindex="-1"><a class="header-anchor" href="#_165-daily-life-asking-for-a-loan"><span>[165] Daily Life - Asking For A Loan</span></a></h3><p>B: Hello Sir may I help you?</p><p>A: Yes. I would like some information for <strong>requesting a loan</strong>.</p><p>B: Very well, here are the general terms of our loan <strong>policies</strong>. We <strong>pride ourselves in</strong> having the lowest interest rate in the country for personal loans.</p><p>A: I see. So <strong>let me get this straight</strong>. If I <strong>borrow</strong> let&#39;s say, ten thousand dollars, how much will I have to pay each month?</p><p>B: It depends on how long you take to <strong>pay it back</strong>. If we lend you ten thousand dollars at an annual <strong>interest rate</strong> of ten percent for forty eight months, you would have to pay each month a portion of the loan which is called the principal and another small portion of the annual interest rate. This of course is considering that you don&#39;t <strong>default</strong> on a payment!</p><p>A: It sounds good but, there is just one problem. I have a terrible <strong>credit score</strong>.</p><p>B: That is a very serious problem you see, the bank must assess your personal information, past loans, assets and any other relevant information such as your credit score in order to approve your loan.</p><p>A: You know what? I don&#39;t really need the money. Thanks anyways!</p><h3 id="_166-daily-life-dr-botox" tabindex="-1"><a class="header-anchor" href="#_166-daily-life-dr-botox"><span>[166] Daily Life Dr. Botox</span></a></h3><p>A: What are you doing?</p><p>B: Look at me. I look so old! I look as if I were thirty.</p><p>A: Come on! Stop being so <strong>vain</strong>. You look great! You are beautiful!</p><p>B: Yes, I am, but I think it&#39;s time for some <strong>plastic surgery</strong>. I&#39;m tired of these <strong>wrinkles</strong> and <strong>sagging skin</strong>. See?</p><p>A: I don&#39;t see any wrinkles or sagging skin! You are 25! Stop beings ridiculous. Besides, I think that people who get <strong>Botox</strong>, have <strong>facelifts</strong>, or tummy tucks look weird. It doesn&#39;t look natural.</p><p>B: Whatever, I think I&#39;m gonna get <strong>liposuction</strong> and a <strong>nose job</strong> and some <strong>breast implants</strong> as well.</p><p>A: I think you need to get brain surgery. I honestly don&#39;t think you need <strong>cosmetic surgery</strong>. You look amazing.</p><p>B: I thought you were my friend and would support me on this! I just want to feel better about myself and feel more attractive.</p><p>A: You don&#39;t need plastic surgery to do that. You are fine the way you are and you have guys drooling all over you! Plus, plastic surgery hurts!</p><p>B: Really?</p><p>A: Yeah! When I got my nose job I was black and blue for a week!</p><h3 id="_167-daily-life-learning-how-to-drive" tabindex="-1"><a class="header-anchor" href="#_167-daily-life-learning-how-to-drive"><span>[167] Daily Life - Learning How To Drive</span></a></h3><p>A: Ok! I&#39;m ready for my driving lesson! Should I start the car?</p><p>B: Hold on there Fittipaldi, first let&#39;s go over things one more time. Now before you even think of starting the car, make sure your seat is at a comfortable position and you can grip the <strong>steering wheel</strong> firmly. Next check your <strong>rear view mirrors</strong> to make sure you can see properly.</p><p>A: We have been through this <strong>a million times</strong>! Let&#39;s get going already! I&#39;m ready!</p><p>B: Fine. Start the car. Ok, now gently step on the <strong>clutch</strong> and <strong>shift to 1st gear</strong>. Good, now accelerate gently and let go of the clutch as you do it. There we go. Good!</p><p>A: I&#39;m doing it! I&#39;m driving! This is awesome! Let&#39;s turn some music on!</p><p>B: Keep your eyes on the road! No music! We are coming up to a red light, step on the brakes. What are you doing? I said the brakes! Look out for those people! Get off the sidewalk!</p><p>A: Get out of my way! This is just like playing video games!</p><p>B: It&#39;s the police! <strong>Pull over</strong>!</p><p>A: <strong>They&#39;ll never take me alive</strong>!</p><h3 id="_168-the-weekend-cooking-a-thanksgiving-dinner" tabindex="-1"><a class="header-anchor" href="#_168-the-weekend-cooking-a-thanksgiving-dinner"><span>[168] The Weekend - Cooking A Thanksgiving Dinner</span></a></h3><p>A: Hello everyone and welcome back to our show. Today we are going to learn how to cook the perfect thanksgiving turkey! I will share a secret that I have kept for over 30 years on how to cook the perfect, most <strong>mouth watering</strong>, juiciest turkey in the world! Let&#39;s get started!</p><p>A: First of all, we must bring out our key ingredient -- whiskey. You see, the grains used to make whiskey along with the alcohol, brings out the flavor of the turkey meat. Let&#39;s pour one cup of whiskey on the turkey, and serve yourself a cup as well! Cheers! Ahhh! That&#39;s good <strong>12-year whiskey</strong> right there. Ok, back to our turkey. Preheat your oven to 475 degrees Fahrenheit. Now have another cup of whiskey.</p><p>A: Now that the oven is hot, we place our <strong>bird</strong> on a <strong>rack</strong> inside a roasting pan. Let&#39;s add some whiskey to give some extra flavor and let&#39;s have another cup. <strong>That hit the spot</strong>. There we go, we can leave it in there for the next 45 minutes. In the meantime, let&#39;s have another sip of whiskey and start with our delicious pumpkin pie.</p><p>A: Lightly <strong>whisk</strong> together 2 eggs and the extra yolk in a large bowl. Once that&#39;s ready we can put sugar, spices such as cloves, <strong>grated</strong> nutmeg and cinnamon with some cream and dark rum into a saucepan. Slowly bring up to <strong>simmering point</strong> stirring occasionally. Now you may notice that we are using some dark rum in this pie. This is because the richness of the pumpkin is beautifully enhanced by the dark rum, so to celebrate this great occasion, for yourself a glass! Cheers!</p><p>A: Now that we have finished with the filling, let&#39;s bake the pie for 45 to 50 minutes until the filling has puffed up around the edges and the center is almost set. All done! A cup of rum to celebrate the completion of this great thanksgiving dinner!</p><p>A: After waiting for an hour, and having a couple of drinks, it&#39;s time to check on our turkey! Take the turkey out of the oven, pick the turkey off of the ground. Don&#39;t worry, it will add flavor to this recipe. Now also remove the pie from the oven and serve while still hot! Cheers and happy thanksgiving!</p><h3 id="_169-the-weekend-roller-coaster" tabindex="-1"><a class="header-anchor" href="#_169-the-weekend-roller-coaster"><span>[169] The Weekend - Roller Coaster</span></a></h3><p>A: I&#39;m so excited! We are finally here! Six Flags Magic Mountain! This is the best <strong>amusement park</strong> in the world!</p><p>B: Alright <strong>settle down now</strong>, you&#39;re gonna give yourself <strong>a heart attack</strong>.</p><p>C: I can&#39;t believe they charged us 35 dollars each. It seems like such a <strong>ripoff</strong> don&#39;t you think? It&#39;s not like I&#39;m gonna get on these things.</p><p>A: Whoa... Viper! That&#39;s the world&#39;s highest and fastest <strong>roller coaster</strong>! You go at more than one hundred <strong>miles per hour</strong>! I wanna go on that one! Can I mom please? Can I ?</p><p>B: Chris I&#39;m not sure you should get on that, it seems a bit too much for you and we just had breakfast 30 minutes ago. I don&#39;t think it&#39;s a good idea.</p><p>A: Aww <strong>come on</strong> mom! <strong>I can handle it</strong>. I promise I won&#39;t ask for anything else! Besides, it&#39;s not like I&#39;m gonna <strong>throw up</strong> or anything...</p><p>C: Let him go Carol, he&#39;ll be fine.</p><p>A: Alright! Yeah! This is amazing! See how high up we&#39;re going? Whoa... mmmf mmfff barf.</p><h3 id="_170-daily-life-wedding-doubts" tabindex="-1"><a class="header-anchor" href="#_170-daily-life-wedding-doubts"><span>[170] Daily Life - Wedding Doubts</span></a></h3><p>A: Man, I&#39;m freaking out! You gotta help me!</p><p>B: Whoa whoa take it easy, relax. Geez, you&#39;re <strong>sweating like a pig</strong>! What&#39;s going on?</p><p>A: I can&#39;t <strong>go through with this</strong>! I just can&#39;t! I&#39;m not ready for <strong>marriage</strong>! What was I thinking? I&#39;m only thirty five years old! I&#39;ve got my entire life ahead of me, adventures waiting! I can&#39;t <strong>settle down</strong> yet!</p><p>B: What are you talking about? It wasn&#39;t more than a month ago that you were rambling on about how you are tired of living the life of a <strong>bachelor</strong> and how you envy your friends that have a family!</p><p>A: I know I know!</p><p>B: Let&#39;s think this through. First of all, you cannot leave Amy at the <strong>altar</strong>. Not only will she be humiliated and kill you, but she is the woman that you love and the woman of your dreams! Why would you want to end that or jeopardize it like this? Second of all, you are just <strong>getting cold feet</strong>. You know deep down inside that you want to marry her, so <strong>cut the crap</strong> and do it!</p><p>B: You&#39;re right. I&#39;m being crazy! Ok, I&#39;m ready, let&#39;s do this!</p><p>A: Great! Phew! That was a close one! <strong>You had me going there for a minute</strong>. I thought I was gonna have to slap some sense into you.</p><h2 id="p171-180" tabindex="-1"><a class="header-anchor" href="#p171-180"><span>P171-180</span></a></h2><h3 id="_171-the-weekend-buying-a-camera" tabindex="-1"><a class="header-anchor" href="#_171-the-weekend-buying-a-camera"><span>[171] The Weekend - Buying a Camera</span></a></h3><p>A: Hello, ma&#39;am, can I help you find something?</p><p>B: Yes, actually I&#39;m looking to buy a camera.</p><p>A: We&#39;ve got a wide selection do you know if you&#39;d like a <strong>point-and-shoot</strong>, or something a little fancier? Are you shopping for yourself or for someone else?</p><p>B: Actually I&#39;m buying a camera for my husband.</p><p>A: Ah, well then I&#39;d recommend a nice <strong>entry-level</strong> <strong>digital SLR</strong>.</p><p>B: Yeah? Can I take a look at the SLRs you carry?</p><p>A: Sure thing, follow me. This here is the.</p><p>B: The Canon Eos. Yeah it&#39;s ok, but I&#39;m looking for something that performs better in low light, has a better <strong>display panel</strong>, and longer battery life.</p><p>A: Oh, ah, um the Nikon D60 is a nice option.</p><p>B: Yeah, but what <strong>kit lens</strong> does this camera come with? I don&#39;t want some bulky <strong>telephoto lens</strong>.</p><p>A: Oh, well this one has the, uh.</p><p>B: Looks to me like an 18-55mm lens. pretty standard, that will do. Not like my husband will be <strong>stalking</strong> celebrities or anything!</p><p>A: So, ahem, can I interest you in any acc...</p><p>B: Accessories? Do you carry <strong>polarizing filters</strong>?</p><p>A: Polarizing filter um we should! I&#39;m sorry, ma&#39;am. looks like we&#39;re sold out.</p><p>B: No you&#39;re not! There are some right here!</p><p>A: Oh, well, would you look at that! Po-la-ri-zing filters.</p><p>B: Thanks for your help, Ralph!</p><p>A: No problem, ma&#39;am.</p><h3 id="_172-daily-life-dry-cleaners" tabindex="-1"><a class="header-anchor" href="#_172-daily-life-dry-cleaners"><span>[172] Daily Life - Dry Cleaners</span></a></h3><p>A: <strong>Thank god</strong> you are open! I have an emergency!</p><p>B: Hello Mr.Henderson what can I do for you?</p><p>A: I need this dress and this suit <strong>dry cleaned</strong> ASAP!</p><p>B: OK, I can have it ready by <strong>the end of the week</strong>.</p><p>A: No you don&#39;t understand, I need this tomorrow morning! I accidentally <strong>spilled</strong> beer all over my wife&#39;s dress and we have a wedding to attend tomorrow! She&#39;s gonna kill me!</p><p>B: Ok, I can have it ready tomorrow afternoon, but this suit is also very <strong>stained</strong>. I can&#39;t guarantee we can remove it completely.</p><p>A: Fine! Can you also <strong>iron</strong> and <strong>starch</strong> this shirt?</p><p>B: Certainly.</p><p>A: Great! This is our secret! If you see my wife, say nothing to her about this!</p><h3 id="_173-the-office-preparing-a-budget" tabindex="-1"><a class="header-anchor" href="#_173-the-office-preparing-a-budget"><span>[173] The Office - Preparing a Budget</span></a></h3><p>A: Welcome Mr and Mrs Carnwell, please take a seat.</p><p>B: Thank you.</p><p>A: So I understand that your family spending has <strong>sky rocketed</strong> and you want to start budgeting.</p><p>C: Yes that&#39;s correct. Frankly speaking our <strong>household income</strong> is relatively high and we have never had any money problems, but I think this is the main reason as to why our spending has gone <strong>out of control</strong>.</p><p>B: We have two kids and with <strong>allowances</strong>, paying their credit cards, ours and not to mention our mortgage and car payments. With the recent economic <strong>downturn</strong>, my husband&#39;s business has suffered and now we need some advice as to how we can prepare a family budget.</p><p>A: I see. Well you have <strong>come to the right place</strong>. First what we need to do, is determine your cash flow. Knowing how much money is coming in will help us <strong>allocate</strong> spending to different categories such as mortgage, education, groceries, etc. (et cetera)</p><p>B: Yes that makes sense.</p><p>A: Secondly, I need you to bring all of your receipts for the last two to three months. That way, we can determine what your average <strong>expenditures</strong> are and see which category you are spending money on the most. Usually, your fixed costs are higher and we can&#39;t do much about that, but we can usually trim your variable costs such as entertainment or clothing.</p><p>C: Great! We will do that then! Now how about we treat you to a nice dinner?</p><p>A: That&#39;s another thing. If you really want to stop spending so much money, throw away at least half of your credit cards!</p><h3 id="_174-the-weekend-getting-a-manicure" tabindex="-1"><a class="header-anchor" href="#_174-the-weekend-getting-a-manicure"><span>[174] The Weekend - Getting a manicure</span></a></h3><p>A: Honey I&#39;ll be right back!</p><p>B: Where are you going?</p><p>A: I told you already! I&#39;m going to <strong>get my nails done</strong>.</p><p>B: Again? You just went last week! You spend more time at the <strong>nail salon</strong> than you do here at home! Honestly, why do you need a manicure every week?</p><p>A: Well, first of all, I like to <strong>pamper</strong> myself, and my nails look great. You should come with me!</p><p>B: Why? I don&#39;t want to have nail polish or anything like that!</p><p>A: They don&#39;t only <strong>paint</strong> my nails! The <strong>manicurist</strong> will remove my <strong>cuticles</strong>, <strong>file</strong> my nails, and apply at least four <strong>coats</strong> of <strong>nail polish</strong>!</p><p>B: Yeah, sounds like something I should definitely do.</p><h3 id="_175-global-view-new-years-resolution" tabindex="-1"><a class="header-anchor" href="#_175-global-view-new-years-resolution"><span>[175] Global View - New Years Resolution</span></a></h3><p>A: Did you read this? It says that the number one new years&#39; resolution people make is to spend more time with friends and family.</p><p>B: Why would that be funny?</p><p>A: Well, think about it. We are a society that is always <strong>on the go</strong>, not because we have to, but because we want to.</p><p>B: Why?</p><p>A: We work hard and spend less time at home because we are trying to provide for our family with <strong>goods and services</strong> that are usually unnecessary.</p><p>B: I don&#39;t agree, but anyways, I think you should start thinking of a new year&#39;s resolution yourself.</p><p>A: What&#39;s the point? We always make a new year&#39;s resolution and by February we will have forgotten about it. It&#39;s pointless.</p><p>B: Well then maybe you should <strong>resolve</strong> to <strong>sticking to</strong> your goals and objectives.</p><p>A: What about you? Your gym bag is <strong>gathering dust</strong> and you still have <strong>brand new</strong> running shoes that are yet to be jogged in.</p><p>B: Well, I would go if you kept your promise of going to the gym with me everyday!</p><p>A: Yeah yeah whatever.</p><h3 id="_176-daily-life-heating" tabindex="-1"><a class="header-anchor" href="#_176-daily-life-heating"><span>[176] Daily Life - Heating</span></a></h3><p>A: It&#39;s <strong>freezing</strong> in here! Can I <strong>turn up</strong> the heat?</p><p>B: Don&#39;t touch that <strong>thermostat</strong>! You don&#39;t pay the bills around here!</p><p>A: Dad! Are you serious? What&#39;s the point of having <strong>central heating</strong> if we can&#39;t use it! Look, I can see my breath!</p><p>B: Put on a sweater! I&#39;m not gonna let you <strong>run up</strong> my heating bill just because it&#39;s a bit <strong>chilly</strong>.</p><p>A: Dad! I&#39;m gonna <strong>catch a cold</strong>!</p><p>B: When I was your age, my parents didn&#39;t have central heating like you do! We had a <strong>furnace</strong> in the center of the living room and that was it. We used it to cook, heat the house and even dry our clothes! We never caught a cold. You should be grateful!</p><h3 id="_177-the-weekend-decorating-a-christmas-tree" tabindex="-1"><a class="header-anchor" href="#_177-the-weekend-decorating-a-christmas-tree"><span>[177] The Weekend - Decorating a Christmas Tree</span></a></h3><p>A: I&#39;m home. Everyone, come here. I bought a <strong>Christmas tree</strong>. Look at this beautiful <strong>pine tree</strong>.</p><p>B: Wow, it&#39;s huge. Are you sure <strong>it will fit</strong> in the living room?</p><p>C: Awesome. I&#39;ll go get the Christmas lights.</p><p>A: Of course it will. Help me put it in the living room.</p><p>C: I found the lights.</p><p>B: I got the Christmas <strong>ornaments</strong>. We could also place these <strong>stockings</strong> next to the <strong>chimney</strong>.</p><p>C: Great idea. While we <strong>decorate</strong> the tree, we can listen to some good old Christmas songs.</p><h3 id="_178-daily-life-finding-the-perfect-present" tabindex="-1"><a class="header-anchor" href="#_178-daily-life-finding-the-perfect-present"><span>[178] Daily Life - Finding the perfect present</span></a></h3><p>A: Bill. Bill! You gotta help me!</p><p>B: What&#39;s wrong? Slow down or you are gonna give yourself a heart attack.</p><p>A: Tomorrow is Christmas and I haven&#39;t bought my mom anything! I&#39;m such a bad son!</p><p>B: <strong>Take it easy</strong>! Let&#39;s go to the mall, window shop a little and see if there is anything she might like.</p><p>A: That&#39;s just it! I don&#39;t know what to get her! Last year I got her a ring that was <strong>two sizes too big</strong> and a pair of shoes five sizes too small! I <strong>suck at</strong> getting presents for people.</p><p>B: That&#39;s where you&#39;re making a big mistake! You can&#39;t just guess peoples&#39; likes or sizes! Especially with clothes or jewelry. On top of that, I think that you should get your mom something that shows how much you love her. At the same time you should show her that you took the time and effort to look for something that she would really like!</p><p>A: Yeah you&#39;re right. <strong>When it comes down to it</strong>, I can be pretty <strong>tacky</strong>.</p><p>B: Yeah <strong>tell me about it</strong>. I know! Your mom is trying to learn Spanish right? Why don&#39;t you get her a <strong>gift certificate</strong> for this great website I saw called SpanishPod.</p><p>A: Now that&#39;s a great idea!</p><h3 id="_179-intermediate-silent-night" tabindex="-1"><a class="header-anchor" href="#_179-intermediate-silent-night"><span>[179] Intermediate - Silent Night</span></a></h3><p>A: Silent night, holy night</p><p>A: All is calm, all is bright</p><p>A: Round yon Virgin Mother and Child</p><p>A: Holy Infant so tender and mild</p><p>A: Sleep in heavenly peace</p><p>A: Sleep in heavenly peace</p><p>A: Silent night, holy night</p><p>A: Shepherds quake at the sight</p><p>A: Glories stream from heaven afar</p><p>A: Heavenly hosts sing Alleluia!</p><p>A: Christ, the Saviour is born</p><p>A: Christ, the Saviour is born</p><p>A: Silent night, holy night</p><p>A: Son of God, love&#39;s pure light</p><p>A: Radiant beams from Thy holy face</p><p>A: With the dawn of redeeming grace</p><p>A: Jesus, Lord, at Thy birth</p><p>A: Jesus, Lord, at Thy birth</p><h3 id="_180-elementary-jingle-bells" tabindex="-1"><a class="header-anchor" href="#_180-elementary-jingle-bells"><span>[180] Elementary - Jingle Bells</span></a></h3><p>A: Dashing through the snow</p><p>A: In a one horse open sleigh</p><p>A: O&#39;er the fields we go</p><p>A: Laughing all the way</p><p>A: Bells on bob tails ring</p><p>A: Making spirits bright</p><p>A: What fun it is to laugh and sing</p><p>A: A sleighing song tonight</p><p>A: Oh, jingle bells, jingle bells</p><p>A: Jingle all the way</p><p>A: Oh, what fun it is to ride</p><p>A: In a one horse open sleigh</p><p>A: jingle bells, jingle bells</p><p>A: Jingle all the way</p><p>A: Oh, what fun it is to ride</p><p>A: In a one horse open sleigh</p><h2 id="p181-190" tabindex="-1"><a class="header-anchor" href="#p181-190"><span>P181-190</span></a></h2><h3 id="_181-daily-life-christmas-day" tabindex="-1"><a class="header-anchor" href="#_181-daily-life-christmas-day"><span>[181] Daily Life - Christmas Day</span></a></h3><p>A: Dad, dad, dad! Wake up! It&#39;s Christmas!</p><p>B: Timmy. It&#39;s too early for this. Look, it&#39;s six in the morning! Go back to bed!</p><p>A: No way! Santa already came and left all our presents! Can we go open them? Please! Please!</p><p>C: Of course we can honey. Bill, come on, get dressed.</p><p>B: Fine! Not like Santa brought me any gifts!</p><p>C: Bill! Honestly, you can be such a grouch sometimes.</p><p>A: Look at all these presents under the Christmas tree! Awesome!</p><p>B: Alright Timmy, knock yourself out. We should get ready and head to the market to buy everything for the Christmas dinner tonight.</p><p>C: Yeah you&#39;re right. It&#39;s the first time we are hosting Christmas dinner at our house so everything has to be perfect.</p><p>B: I got the list right here. Ham, turkey, mashed potatoes, ingredients for the gravy and of course, yams!</p><p>C: My dad offered to bring the eggnog so we should be set!</p><h3 id="_182-global-view-boxing-day" tabindex="-1"><a class="header-anchor" href="#_182-global-view-boxing-day"><span>[182] Global View - Boxing Day</span></a></h3><p>A: What do you think of this one?</p><p>B: Eh, so so.</p><p>A: And this one? Too flashy?</p><p>B: Nah, not too flashy.</p><p>A: Uhg! And this sweater from my aunt? Isn&#39;t it hideous?</p><p>B: I guess.</p><p>A: Are you even listening? I&#39;m trying to have a conversation with you.</p><p>B: And I&#39;m trying to watch the game, but you&#39;re yapping on about your new clothes!</p><p>A: Well I have to decide which gifts to keep and which to exchange for better ones when I go to the Boxing Day sales this afternoon!</p><p>B: Well could you do me the favor of making this quick? It&#39;s the third quarter and you&#39;ve been blabbering on since the first!</p><p>A: Oh, your precious game. You watch the same game every year, and each year your beloved hometown team loses by at least three goals!</p><p>B: Oh no you didn&#39;t. You didn&#39;t just insult the Salsbury Seals, did you? Why don&#39;t you just. just go and return all of those stupid clothes and not come back until the sales are over?</p><p>A: I might just! Enjoy your stupid game!</p><p>B: And Merry Christmas!</p><p>A: Merry Christmas!</p><h3 id="_183-daily-life-winter-clothes" tabindex="-1"><a class="header-anchor" href="#_183-daily-life-winter-clothes"><span>[183] Daily Life - Winter Clothes</span></a></h3><p>A: Bye, mom!</p><p>B: Wait, Jimmy, it&#39;s cold outside. Put a hat on!</p><p>A: Ok. Bye!</p><p>B: No, wait, you will be too cold without mittens.</p><p>A: Alright. See ya!</p><p>B: Hold on, with that wind, you&#39;re going to catch a cold. Wear this scarf.</p><p>A: Ok, see you after school...</p><p>B: Oh... and ear muffs! Put these on... here we go.</p><p>A: Mom?</p><p>B: Yes, honey...</p><p>A: I... I can&#39;t breathe.</p><h3 id="_184-daily-life-fresh-start" tabindex="-1"><a class="header-anchor" href="#_184-daily-life-fresh-start"><span>[184] Daily Life - Fresh Start</span></a></h3><p>A: Now that it&#39;s the new year, I&#39;ve decided to turn over a new leaf.</p><p>B: Yeah? You finally decided to wipe the slate clean?</p><p>A: You got it! I have a new job, I&#39;m living in a new city, with new friends! This is my opportunity to make some small changes in the way I live my life.</p><p>B: So what are you going to do? Take up an art class or something?</p><p>A: Well, first of all, I&#39;ve decided to stop smoking. It&#39;s not that I&#39;m pinching pennies or anything, it&#39;s just that I&#39;ve been smoking since I was sixteen, and I think it&#39;s time to stop.</p><p>B: I&#39;m with you on that one. Anything else you&#39;re planning on doing?</p><p>A: One last thing, I&#39;ve decided to come out of the closet.</p><p>B: It&#39;s about time!</p><h3 id="_185-the-weekend-farm-animals" tabindex="-1"><a class="header-anchor" href="#_185-the-weekend-farm-animals"><span>[185] The Weekend - Farm Animals</span></a></h3><p>A: Isn&#39;t this great? I always wanted to own a farm, live out in the country, grow my own food!</p><p>B: This is very beautiful. Though I have to confess, I don&#39;t know the first thing about farming!</p><p>A: That&#39;s fine! Don&#39;t worry about it!</p><p>B: What was that?</p><p>A: Relax, it was just a goat!</p><p>B: And that?</p><p>A: It&#39;s just the cows that are grazing over there. We can milk them later.</p><p>B: What was that?</p><p>A: Honey, seriously, It&#39;s just a sheep. Relax!</p><p>A: Relax, that was just the horses and donkeys that are in the stable .</p><p>B: You know what? I don&#39;t think I can hack it here out in the countryside. I&#39;m going back to the city!</p><h3 id="_186-the-office-business-plan" tabindex="-1"><a class="header-anchor" href="#_186-the-office-business-plan"><span>[186] The Office - Business Plan</span></a></h3><p>A: I&#39;ve had it! I&#39;m done working for a company that is taking me nowhere!</p><p>B: So what are you gonna do? Just quit?</p><p>A: That&#39;s exactly what I am going to do! I&#39;ve decided to create my own company! I&#39;m going to write up a business plan, get some investors and start working for myself!</p><p>B: Have you ever written up a business plan before?</p><p>A: Well, it can&#39;t be that hard! I mean, all you have to do is explain your business, how you are going to do things and that&#39;s it, right?</p><p>B: You couldn&#39;t be more wrong! A well written business plan will include an executive summary which highlights the idea of the business in two pages or less. Then you need to describe your company with information such as what type of legal structure it has, history, etc.</p><p>A: Well that seems easy enough.</p><p>B: Wait, there&#39;s more! Then you need to introduce and describe your goods or services. What they are and how they are different from competitors&#39;? Then comes the hard part, a market analysis. You need to investigate and analyze hundreds of variables! You need to take into consideration socioeconomic factors from GDP per capita to how many children on average the population has! All this information is useful so that you can move on to your strategy and implementation stage, where you will describe in detail how you will actually execute your idea.</p><p>A: Geez. Is that all?</p><p>B: Almost, the most important piece of information for your investors will be the financial analysis. Here you will calculate and estimate sales, cash flow and profits. After all, people will want to know when they will begin to see a return on their investment!</p><p>A: Umm. I think I&#39;ll just stick to my old job and save myself all the hassle of trying to start up a business!</p><h3 id="_187-daily-life-going-on-a-diet" tabindex="-1"><a class="header-anchor" href="#_187-daily-life-going-on-a-diet"><span>[187] Daily Life - Going On A Diet</span></a></h3><p>A: Oh man! I&#39;ve been starving myself for days now and I haven&#39;t lost an ounce!</p><p>B: Are you trying to lose weight?</p><p>A: Yeah, my friend is getting married next month and I&#39;m supposed to be a bridesmaid. I have to fit into my dress and look nice for her wedding, but I haven&#39;t lost any weight! Look at these love handles.</p><p>B: You don&#39;t have to starve yourself to lose weight. I think that&#39;s where you&#39;re going wrong.</p><p>A: Why? If I eat less, then my body will start eating away at my fat reserves right?</p><p>B: Not really. You should try to not eat foods high in calories, salts or saturated fats. Stay away from oily food and artificial flavors.</p><p>A: So you are saying that I should eat, but I should just watch what I eat?</p><p>B: Yes! You can also try to reduce your intake of carbohydrates and foods that are high in cholesterol. You can have steamed veggies or increase your protein intake found in chicken or fish.</p><p>A: If I do all this do you think I can lose twenty pounds in four weeks?</p><p>B: Don&#39;t count on it.</p><h3 id="_188-the-office-asking-for-a-raise" tabindex="-1"><a class="header-anchor" href="#_188-the-office-asking-for-a-raise"><span>[188] The Office - Asking For A Raise</span></a></h3><p>A: Excuse me sir, may I talk to you?</p><p>B: Bill! Sure, come on in. What can I do for you?</p><p>A: Well sir, as you know, I have been an employee of this prestigious firm for over ten years.</p><p>B: Yes.</p><p>A: I won&#39;t beat around the bush. Sir, I would like a raise. I currently have three companies after me and so I decided to talk to you first.</p><p>B: A raise? Son, I would love to give you a raise, but this is just not the right time.</p><p>A: I understand your position, and I know that the current economic downturn has had a negative impact on sales, but you must also take into consideration my hard work, pro-activeness and loyalty to this company for over a decade.</p><p>B: Taking into account these factors, and considering I don&#39;t want to start a brain drain, I&#39;m willing to offer you a ten percent raise and an extra five days of vacation time. How does that sound?</p><p>A: Great! It&#39;s a deal! Thank you, sir!</p><p>B: Before you go, just out of curiosity, what companies were after you?</p><p>A: Oh, the electric company, gas company and water company!</p><h3 id="_189-daily-life-buying-a-new-mobile-phone" tabindex="-1"><a class="header-anchor" href="#_189-daily-life-buying-a-new-mobile-phone"><span>[189] Daily Life - Buying A New Mobile Phone</span></a></h3><p>A: Hello sir, may I help you?</p><p>B: Yeah, I accidentally dropped my phone in the toilet.</p><p>A: I see. Well, you have come to the right place. We have over one hundred models of more than twenty leading mobile phone manufacturers.</p><p>B: Sounds good. I don&#39;t want it to be too expensive, maybe something mid-range.</p><p>A: We have this new HTC smart phone. It comes with the Android OS so you can download applications. It also has a built-in camera, mp3 player and touch screen. It works on the 3G network so you have fast access to the internet wherever you are.</p><p>B: What about Wi-fi?</p><p>A: Of course! You can access the internet from any hotspot as well as from home.</p><p>B: One last thing. Is it waterproof?</p><h3 id="_190-the-weekend-family-barbecue" tabindex="-1"><a class="header-anchor" href="#_190-the-weekend-family-barbecue"><span>[190] The Weekend - Family Barbecue</span></a></h3><p>A: Is everything ready for the big family barbecue tomorrow?</p><p>B: Yep. The steaks and chicken are marinated and I also bought hamburger buns.</p><p>A: We should also cook a couple dozen hot dogs and kebabs.</p><p>B: Yeah, good idea. We can put some lawn furniture outside next to the grill. I also set up the tent outside so we can hide from the sun if it gets too hot.</p><p>A: Great! I asked Grace to bring cups and serviettes as she is also bringing two big coolers for the beers.</p><p>B: This is gonna be a great barbecue!</p><h2 id="p191-200" tabindex="-1"><a class="header-anchor" href="#p191-200"><span>P191-200</span></a></h2><h3 id="_191-global-view-daylight-savings-time" tabindex="-1"><a class="header-anchor" href="#_191-global-view-daylight-savings-time"><span>[191] Global View - Daylight Savings Time</span></a></h3><p>A: Did you set your clock forward for daylight savings time?</p><p>B: What? Why do we have to do that?</p><p>A: Well, at the start of the spring we usually have more daylight in the mornings and less in the afternoon. This is basically due to our position on the planet and the rotation of the earth. In any case, to take better advantage of the daylight available, we compensate by moving our clocks forward one hour.</p><p>B: I see. That&#39;s convenient! I never understood things like this, such as GMT. I never know what time zone we are in or when to change my clock!</p><p>A: That just stands for Greenwich Mean Time. Here in California, we are in Pacific Standard Time, that is eight time zones west of Greenwich. Remember when we were in Beijing? Well, then we were in China Standard Time, and that&#39;s eight time zones east of Greenwich!</p><p>B: That&#39;s why it was so weird traveling from Beijing to LA! Because of the huge time difference, even though we left Beijing at noon and flew for more than eight hours, we still arrived in LA the same day at noon! It&#39;s like we went back in time!</p><h3 id="_192-global-view-natural-disasters" tabindex="-1"><a class="header-anchor" href="#_192-global-view-natural-disasters"><span>[192] Global View - Natural Disasters</span></a></h3><p>A: Those are the headlines for today, and now for the international weather report with Mike Sanderson.</p><p>B: Thank you, Bob! This past week has been the beginning of Armageddon for many, a series of unprecedented meteorological events occurred around the world. In Switzerland, a major avalanche was reported in the Alps. Fortunately, no one was injured. Due to to the extreme cold this winter, a blizzard has struck the US Midwest, causing classes in schools and universities to be temporarily canceled.</p><p>B: Moving to to Latin American, Ecuador has suffered a six month drought that has not only affected farming, but has also forced the closure of the hydroelectric power plant that provides electricity for the entire country. In Chile, a major earthquake that registered seven point five on the Richter scale struck the southern region. Losses are reported to be in the billions. Authorities have not yet released an official statement.</p><p>A: Not a great week for the world! Any good news?</p><p>B: I&#39;m afraid not, Bob. One of the major volcanoes in Mexico has erupted, causing major floods and landslides in the region. Meanwhile, Mexico &#39;s coast has been hit by hurricane Liliana and officials say that all the seismic activity leads them to believe that a tsunami may hit Central America, affecting Honduras, Guatemala and Panama. That&#39;s all the news we have for today, but stay tuned for updates on the six o&#39;clock news. Back to you Bob.</p><h3 id="_193-daily-life-building-your-dream-home" tabindex="-1"><a class="header-anchor" href="#_193-daily-life-building-your-dream-home"><span>[193] Daily Life - Building Your Dream Home</span></a></h3><p>A: Mr. and Mrs. Robinson! Let&#39;s get straight to it. You have saved up your money for years and are now ready to build your dream home. What did you have in mind?</p><p>B: A suburban bungalow straight out of the sixties! A perfect lawn with minimal landscaping. A brick patio in the backyard with an old-fashioned grill, quaint lawn furniture, and a swimming pool. A two-car carport, pastel siding and a gable roof. Completed with white shutters and a white picket fence !</p><p>C: Uh, honey?</p><p>B: In the living room we would have moss-green rugs and a fireplace with a stone mantle and wood paneling on the walls. In the kitchen, the cupboards would be a pale yellow and we would have a turquoise metal oven and vinyl flooring -</p><p>C: Umm, sweetie, but I was thinking of a more modern style house. An open concept house, all glass, wood, metal, and concrete.</p><p>B: But sweetums, there is always a lot of wasted space in those kinds of homes. Besides, it&#39;s just a fad. It doesn&#39;t have the homey feeling the old homes do.</p><p>C: Sweetie-pie it&#39;s not a lot of wasted space. It is relaxing and the house would be eco-friendly with an in-floor heating system and designed to retain the heat of the sun in the winter and keep the house cool in the summer. We would have solar panels on the roof -</p><p>B: Do you know how much those things cost?</p><p>C: What about your vintage furniture, dearest? And instead of a lawn, which is also a lot of wasted space and would require environmentally harmful pesticides, we would have a fish pond in the backyard and a garden that would cover the whole yard so we could grow our own food!</p><p>B: But buttercup, I thought you always said that you loved visiting your grandmother&#39;s house!</p><p>C: And I thought you, Mr. Scientist, were all up on saving the planet with your technological advancements!</p><p>A: Umm well I am just going to go get some coffee while you two keep discussing.</p><h3 id="_194-the-weekend-stir-fry" tabindex="-1"><a class="header-anchor" href="#_194-the-weekend-stir-fry"><span>[194] The Weekend - Stir Fry</span></a></h3><p>A: Oh, man. I had the best supper last night. My wife made a stir fry and it was amazing!</p><p>B: I love stir fry Crispy bite-sized vegetables covered in a mixture of soy sauce and oyster sauce. Wilted greens and fresh bean sprouts. Throw in some onion and garlic and ginger! Mmm! Mmm! It&#39;s almost lunchtime. I would die for a plate of stir fry right now!</p><p>A: Well, you can keep the vegetables, I&#39;ll take the meat. The stir fry my wife made was really hearty, with chunks of beef and slivers of bell peppers and onion...</p><p>B: What? You call that a stir fry? More meat than vegetables? That&#39;s the worst insult you could throw at a Chinese stir fry What a disgrace to the wok she fried it in! What you had is equivalent to a fajita without the wrap! Silly Americans!</p><h3 id="_195-global-view-job-hunting" tabindex="-1"><a class="header-anchor" href="#_195-global-view-job-hunting"><span>[195] Global View - Job Hunting</span></a></h3><p>A: Woo hoo! This just might be the start of the rest of my life!</p><p>B: What happened?</p><p>A: I&#39;m in the market for a job! I went on a website with hundreds of job listings in the area and browsed through them until I got the names of a few employers I would like to work for. I have the resume I wrote for English class last month and a cover letter will be a piece of cake to write. I&#39;ve even done my research and found the names of the managers so I can address the letters personally. And you know I can be charming in interviews. Goodbye my penniless days! Hello salary and a career!</p><p>B: Ben, we&#39;re fifteen. What kind of job are you looking for?</p><p>A: Oh, just for a position as a gas station attendant. You know, starting at a simple lowly job, just like all the greats before they made it big in the world.</p><p>B: Uh-huh.</p><p>A: But I&#39;m just in it for the money, right? How else am I going to be able to afford to keep taking Angela to the movies? Besides, I love the smell of gasoline, don&#39;t you?</p><h3 id="_196-daily-life-going-to-the-tailor" tabindex="-1"><a class="header-anchor" href="#_196-daily-life-going-to-the-tailor"><span>[196] Daily Life - Going To The Tailor</span></a></h3><p>A: Welcome to Bill&#39;s Fabric World. What can I do for you today?</p><p>B: I was wondering if you guys also tailor clothes?</p><p>A: Sure we do! We have the best tailors in the country! What is it that you need exactly?</p><p>B: Well, I&#39;m looking to get a custom-made suit.</p><p>A: Excellent! We have the finest cashmeres at affordable prices. How about we get you measured? Let&#39;s start off by measuring the width of your shoulders. Now, let&#39;s measure the length of your arms and this bit around your neck here.</p><p>B: Can you make sure you leave a little extra space in the collar? My neck gets easily irritated.</p><p>A: No problem! Now for your pants, let me just measure your waist and the inseam.</p><p>B: You might also want to leave a little extra room in the waist area. I tend to gain a few pounds over the holidays.</p><p>A: OK. Now you can pick your fabric and pattern design. Please follow me.</p><h3 id="_197-global-view-calling-911" tabindex="-1"><a class="header-anchor" href="#_197-global-view-calling-911"><span>[197] Global View - Calling 911</span></a></h3><p>A: Alright class, now that we&#39;re all dressed up let&#39;s see what professions you chose. Ah, I see a fireman, a police officer, a medic, and a lifeguard! Can anyone tell me what these people have in common?</p><p>B: They save people from bad things?</p><p>A: That&#39;s right! Now class, if something bad happened and you had to get help, do you know what phone number you would call?</p><p>C: 911!</p><p>A: Yes, you would pick up the phone and dial 911. What are some emergency situations where you would need to dial 911?</p><p>B: If my grandpa has a heart attack!</p><p>C: If there is an accident!</p><p>B: If a robber breaks into the house!</p><p>C: If the fire alarm goes off!</p><p>B: Pff! I wouldn&#39;t call 911 if the fire alarm went off in my house. The only time that ever happens is when we&#39;re having spaghetti for supper, and Mom burns the garlic bread, as usual.</p><h3 id="_198-daily-life-applying-cpr" tabindex="-1"><a class="header-anchor" href="#_198-daily-life-applying-cpr"><span>[198] Daily Life - Applying CPR</span></a></h3><p>A: Hello everyone and welcome to our CPR for beginners course. First of all, does anyone know what CPR stands for?</p><p>B: Cardiopulmonary resuscitation!</p><p>A: That&#39;s right! We apply CPR in the case of cardiac arrest or pulmonary arrest.</p><p>B: What does that mean?</p><p>A: Well, basically if your heart stops pumping blood, or your lungs stop pumping air, then we need to get them going again! That&#39;s when we have to apply this procedure. Let&#39;s begin! I need a volunteer.</p><p>B: Me! Me!</p><p>A: Alright, come here and lay flat on your back. Let&#39;s suppose this young woman has stopped breathing. We must lift the person&#39;s chin so that we clear a pathway for air to get into the lungs. Then we place our mouth over the other person&#39;s mouth and blow air two or three times, like this.</p><p>B: Wait, what are you doing? I&#39;m a married woman! You can&#39;t just try to kiss me like this!</p><p>A: Ma&#39; am I&#39;m not trying to kiss you! I am trying to demonstrate how to apply CPR in the case of an emergency.</p><p>B: Well, ok. But no French kissing!</p><p>A: As I was saying, we blow air through the mouth in this manner. Once this is done, we must try to get the heart going again. To do this, we place our hands over the person&#39;s chest, and press down firmly two or three times.</p><p>B: Wait, what are you doing! You can&#39;t just kiss me then go for second base!</p><h3 id="_199-global-view-learning-about-first-aid" tabindex="-1"><a class="header-anchor" href="#_199-global-view-learning-about-first-aid"><span>[199] Global View - Learning About First Aid</span></a></h3><p>A: Hey Joe! Where have you been these past few days?</p><p>B: I&#39;ve been busy with a first aid course that I started about a week ago at the Red Cross.</p><p>A: Cool! I&#39;ve always wanted to do something like that! Have you learned anything useful?</p><p>B: For sure! I mean we&#39;ve learned how to apply pressure to stop bleeding, how to check for a pulse, and even how to apply CPR!</p><p>A: Have you treated any real emergencies?</p><p>B: Well, they took us along with some paramedics. There was this guy who fell off his motorcycle and suffered a concussion as well as a couple of compound fractures. His wounds were pretty serious so they had to rush him to the hospital. It was intense!</p><p>A: I can imagine! I tend to faint when I see blood, so I think I won&#39;t be taking up a course like that anytime soon!</p><h3 id="_200-daily-life-junk-food" tabindex="-1"><a class="header-anchor" href="#_200-daily-life-junk-food"><span>[200] Daily Life - Junk Food</span></a></h3><p>A: I&#39;m hungry, let&#39;s grab a bite to eat.</p><p>B: Sure! How about we go home and prepare a couple of sandwiches?</p><p>A: Nah! Let&#39;s go get a burger and fries.</p><p>B: All you ever do is have unhealthy fast food Pizza, fries, burgers and hot dogs! You have to start eating better!</p><p>A: What are you talking about? I have salads sometimes.</p><p>B: Yeah right! I&#39;m serious! You should also cut down on your sugar intake as well. You drink carbonated drinks that are high in fructose syrup! It&#39;s really not healthy!</p><p>A: Fine! I&#39;ll start drinking and having home cooked meals that are low in fat. Are you happy now?</p><p>B: It&#39;s a start, but I&#39;ll be happy when I see you stick to your promise!</p>',533)])])}const l=t(s,[["render",r]]),p=JSON.parse(`{"path":"/English/EnglishPod/EnglishPod_151-200/","title":"EnglishPod_151-200","lang":"en-US","frontmatter":{"title":"EnglishPod_151-200","permalink":"/English/EnglishPod/EnglishPod_151-200/","createTime":"2026/06/30 08:10:21","description":"P151-160 [151] Advanced - Darwin's Theory Of Evolution A: Man, it's been forever. Where have you been up lately? B: I've been busy preparing for my exams, not to mention all the...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"EnglishPod_151-200\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://docs.threekd.com/English/EnglishPod/EnglishPod_151-200/"}],["meta",{"property":"og:site_name","content":"Di's Docs"}],["meta",{"property":"og:title","content":"EnglishPod_151-200"}],["meta",{"property":"og:description","content":"P151-160 [151] Advanced - Darwin's Theory Of Evolution A: Man, it's been forever. Where have you been up lately? B: I've been busy preparing for my exams, not to mention all the..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"en-US"}]]},"git":{"createdTime":1782779198000},"autoDesc":true,"filePathRelative":"English/EnglishPod/EnglishPod_151-200.md","headers":[]}`);export{l as comp,p as data};
